# Surah Yunus (chapter 10) — part 10: ayat 91-100 (IDs 1455-1464)
SURAH = 10

ENTRIES = {
1455: (
"کیا — اب — حالانکہ — تم — پہلے — نافرمانی کرتے تھے — اور — فساد کرنے والوں — میں — سے — تھے",
"""۱۔ فرعون — کا — آخری — ایمان — قبول نہیں کیا گیا۔
۲۔ ’’آلْآنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ الْمُفْسِدِينَ‘‘ — کیا — اب — حالانکہ — تم — پہلے — نافرمانی کرتے تھے — اور — فساد کرنے والوں — میں — سے — تھے — یعنی اب — ایمان — لائے ہو — حالانکہ تم — پہلے — نافرمانی کرتے تھے — اور مفسدوں — میں — سے تھے۔
۳۔ عملی سبق: عذاب کے وقت — ایمان — قبول نہیں؛ وقت سے پہلے ایمان — لاؤ۔"""
),
1456: (
"پس — آج — ہم — تمہارے — جسم — کو — محفوظ رکھیں گے — تاکہ — تم — اپنے — پیچھے — والوں — کے لیے — نشانی — بنو — اور — بے شک — بہت سے لوگ — ہماری آیات — سے — غافل ہیں",
"""۱۔ فرعون کے جسم — کو — نشانی — بنا کر — محفوظ رکھا گیا (محفوظ preserved body)۔
۲۔ ’’فَالْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ آيَۃً وَإِنَّ كَثِيرًا مِّنَ النَّاسِ عَنْ آيَاتِنَا لَغَافِلُونَ‘‘ — پس — آج — ہم — تمہارے — جسم — کو — محفوظ رکھیں گے — تاکہ — تم — اپنے — پیچھے — والوں — کے لیے — نشانی — بنو — اور — بے شک — بہت سے لوگ — ہماری آیات — سے — غافل ہیں — یعنی ہم — تمہارے جسم — کو محفوظ رکھیں گے — تاکہ — تم — بعد والوں کے لیے نشانی — بنو — اور — بہت سے لوگ ہماری آیات — سے — غافل ہیں۔
۳۔ عملی سبق: فرعون — کی لاش — آج بھی — نشانی — ہے؛ غفلت — نہ کرو۔"""
),
1457: (
"اور — ہم — نے — بنی اسرائیل — کو — اچھے — ٹھکانے — عطا کیے — اور — ان — کو — پاکیزہ چیزیں — رزق — دیں — پس — ان — میں — سے — اختلاف — نہ ہوا — جب تک — ان — کے پاس — علم — نہ آیا — بے شک — تمہارا — رب — ان — کے درمیان — قیامت کے دن — ان — باتوں — میں فیصلہ کرے گا — جن — میں — وہ — اختلاف کرتے تھے",
"""۱۔ بنی اسرائیل — عزت — دی گئی — مگر — علم آنے کے بعد — اختلاف — کرنے لگے۔
۲۔ ’’وَلَقَدْ بَوَّأْنَا بَنِي إِسْرَائِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَاهُم مِّنَ الطَّيِّبَاتِ فَمَا اخْتَلَفُوا حَتَّىٰ جَاءَهُمُ الْعِلْمُ إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَۃِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ‘‘ — اور — ہم — نے — بنی اسرائیل — کو — اچھے — ٹھکانے — عطا کیے — اور — ان — کو — پاکیزہ چیزیں — رزق — دیں — پس — ان — میں — سے — اختلاف — نہ ہوا — جب تک — ان — کے پاس — علم — نہ آیا — بے شک — تمہارا — رب — ان — کے درمیان — قیامت کے دن — ان — باتوں — میں فیصلہ کرے گا — جن — میں — وہ — اختلاف کرتے تھے — یعنی بنی اسرائیل — کو — اچھے ٹھکانے اور پاکیزہ رزق دیا — مگر علم آنے کے بعد — اختلاف — کرنے لگے؛ قیامت میں — اللہ — فیصلہ — کرے گا۔
۳۔ عملی سبق: علم — ہونے کے بعد بھی اختلاف — آخرت میں محاسبہ — ہے۔"""
),
1458: (
"پس — اگر — آپؐ — اس — بارے میں — کہ — ہم — نے — آپ کی طرف — نازل کیا — آپ — کو — شک ہے — تو — آپ ان لوگوں سے — جو — آپ — سے پہلے — کتاب — پڑھتے ہیں — پوچھ لیں — یقیناً — آپ کے پاس — حق — آپ — کے رب کی طرف سے — آیا — پس — آپ — ہرگز — شک کرنے والوں — میں سے — نہ ہوں",
"""۱۔ نبیؐ — کو حکم دیا گیا — کتاب والوں سے — پوچھ لیں — حق ثابت ہے۔
۲۔ ’’فَإِن كُنتَ فِي شَكٍّ مِّمَّا أَنزَلْنَا إِلَيْكَ فَاسْأَلِ الَّذِينَ يَقْرَءُونَ الْكِتَابَ مِن قَبْلِكَ لَقَدْ جَاءَكَ الْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ‘‘ — پس — اگر — آپؐ — اس — بارے میں — کہ — ہم — نے — آپ کی طرف — نازل کیا — آپ — کو — شک ہے — تو — آپ ان لوگوں سے — جو — آپ — سے پہلے — کتاب — پڑھتے ہیں — پوچھ لیں — یقیناً — آپ کے پاس — حق — آپ — کے رب کی طرف سے — آیا — پس — آپ — ہرگز — شک کرنے والوں — میں سے — نہ ہوں — یعنی آپؐ — کو حق — رب کی طرف سے — آیا ہے — شک کرنے والوں — میں — سے نہ ہوں؛ ضرورت ہو تو — کتاب والوں سے پوچھ لیں۔
۳۔ عملی سبق: حق — ثابت — ہے؛ شک — بے بنیاد ہے۔"""
),
1459: (
"اور — ان — لوگوں میں — سے — نہ ہوں — جنہوں نے — اللہ — کی آیات — کو — جھٹلا دیا — کہ — آپ — نقصان اٹھانے والوں — میں سے — ہو جائیں",
"""۱۔ جھٹلانے والوں کے ساتھ — شامل — نہ ہوں۔
۲۔ ’’وَلَا تَكُونَنَّ مِنَ الَّذِينَ كَذَّبُوا بِآيَاتِ اللَّهِ فَتَكُونَ مِنَ الْخَاسِرِينَ‘‘ — اور — ان — لوگوں میں — سے — نہ ہوں — جنہوں نے — اللہ — کی آیات — کو — جھٹلا دیا — کہ — آپ — نقصان اٹھانے والوں — میں سے — ہو جائیں — یعنی اللہ کی آیات کو — جھٹلانے والوں — میں — شامل — نقصان — ہے۔
۳۔ عملی سبق: جھٹلانے سے — بچیں؛ خسارہ — آخرت میں ہے۔"""
),
1460: (
"بے شک — وہ لوگ جن — پر — آپ — کے رب — کی — بات — ثابت ہو گئی — وہ — ایمان — نہ لائیں گے",
"""۱۔ جو — اللہ نے مقدر کر دیا کہ ایمان نہیں لائیں گے — وہ نہیں لائیں گے۔
۲۔ ’’إِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ‘‘ — بے شک — وہ لوگ جن — پر — آپ — کے رب — کی — بات — ثابت ہو گئی — وہ — ایمان — نہ لائیں گے — یعنی جن — پر اللہ کی بات — ثابت ہو گئی — وہ — ایمان — نہیں لائیں گے۔
۳۔ عملی سبق: فیصلے — اللہ کے ہاتھ میں؛ ہدایت — صرف اس کی طرف سے۔"""
),
1461: (
"اگرچہ — ان — کے پاس — ہر نشانی — آ جائے — یہاں تک کہ — وہ — دردناک عذاب — دیکھ لیں",
"""۱۔ کوئی نشانی — انہیں ایمان — نہیں دلا سکتی۔
۲۔ ’’وَلَوْ جَاءَتْهُمْ كُلُّ آيَۃٍ حَتَّىٰ يَرَوُا الْعَذَابَ الْأَلِيمَ‘‘ — اگرچہ — ان — کے پاس — ہر نشانی — آ جائے — یہاں تک کہ — وہ — دردناک عذاب — دیکھ لیں — یعنی کوئی نشانی بھی — انہیں — ایمان — نہیں دلائے گی — یہاں تک کہ دردناک عذاب — دیکھ لیں۔
۳۔ عملی سبق: ہدایت — مرضی پر منحصر ہے؛ کوئی نشانی — مجبور نہیں کر سکتی۔"""
),
1462: (
"پس — کوئی — بستی — ایمان — نہ لائی — جس — پر — اس کا — ایمان لانا فائدہ — دے — سوائے — یونس کی قوم — کے — جب — انہوں نے — ایمان لایا — تو — ہم — نے — ان — سے دنیا کی زندگی میں — رسوائی — کا عذاب — ہٹا دیا — اور — ہم — نے — ان — کو — ایک — مدت تک — لطف اندوز — رکھا",
"""۱۔ یونس کی قوم — نینویٰ — نے عذاب دیکھ کر ایمان لایا — اور نجات ملی۔
۲۔ ’’فَلَوْلَا كَانَتْ قَرْيَۃٌ آمَنَتْ فَنَفَعَهَا إِيمَانُهَا إِلَّا قَوْمَ يُونُسَ لَمَّا آمَنُوا كَشَفْنَا عَنْهُمْ عَذَابَ الْخِزْيِ فِي الْحَيَاۃِ الدُّنْيَا وَمَتَّعْنَاهُمْ إِلَىٰ حِينٍ‘‘ — پس — کوئی — بستی — ایمان — نہ لائی — جس — پر — اس کا — ایمان لانا فائدہ — دے — سوائے — یونس کی قوم — کے — جب — انہوں نے — ایمان لایا — تو — ہم — نے — ان — سے دنیا کی زندگی میں — رسوائی — کا عذاب — ہٹا دیا — اور — ہم — نے — ان — کو — ایک — مدت تک — لطف اندوز — رکھا — یعنی عذاب دیکھ کر ایمان — عام طور پر بے فائدہ — ہے — مگر یونس کی قوم — نینویٰ — ایمان — لائی — اور عذاب ہٹا دیا گیا — اور انہیں — مدت تک فائدہ دیا گیا۔
۳۔ عملی سبق: توبہ — حتیٰ کہ عذاب کے سامنے — بھی قبول ہو سکتی ہے — یونسؑ کی قوم — مثال ہے۔"""
),
1463: (
"اور — اگر — آپ کا رب چاہتا — تو — زمین والے — سب — ایمان — لاتے — کیا — آپ — زبردستی — لوگوں کو — مومن بنا دیں",
"""۱۔ اللہ — جب چاہے — سب کو ایمان — دلا دے — مگر — وہ — چاہتا نہیں۔
۲۔ ’’وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَن فِي الْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ النَّاسَ حَتَّىٰ يَكُونُوا مُؤْمِنِينَ‘‘ — اور — اگر — آپ کا رب چاہتا — تو — زمین والے — سب — ایمان — لاتے — کیا — آپ — زبردستی — لوگوں کو — مومن بنا دیں — یعنی اگر اللہ — چاہتا — تو زمین والے — سب ایمان لاتے؛ آپؐ — زبردستی لوگوں کو — مومن — نہیں بنا سکتے۔
۳۔ عملی سبق: ایمان — زبردستی — نہیں آتا؛ دل کا عمل ہے۔"""
),
1464: (
"اور — کسی شخص — کو — ایمان لانے — کا — حق نہیں — مگر — اللہ کی اجازت سے — اور — وہ — ان لوگوں پر — جو — نہیں سمجھتے — ناپاکی ڈالتا ہے",
"""۱۔ ایمان — صرف اللہ کی اجازت سے — حاصل ہوتا ہے۔
۲۔ ’’وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ اللَّهِ وَيَجْعَلُ الرِّجْسَ عَلَى الَّذِينَ لَا يَعْقِلُونَ‘‘ — اور — کسی شخص — کو — ایمان لانے — کا — حق نہیں — مگر — اللہ کی اجازت سے — اور — وہ — ان لوگوں پر — جو — نہیں سمجھتے — ناپاکی ڈالتا ہے — یعنی ایمان — صرف اللہ کی اجازت سے — ہوتا ہے؛ وہ — ان لوگوں پر — جو سمجھتے نہیں — ناپاکی — ڈالتا ہے۔
۳۔ عملی سبق: ہدایت — اللہ کی اجازت سے — ملتی ہے؛ اس سے مانگو۔"""
),
}
